#include <stddef.h>

long long inversions(const long long *xs, long long n) {
    long long count = 0;
    for (long long i = 0; i < n; i++) {
        long long x = xs[i];
        for (long long j = i + 1; j < n; j++)
            if (xs[j] < x)
                cnt++;
    }
    return count;
}

#include <assert.h>
#include "inversions.c"

int main(void) {
    assert(inversions((long long[]){3, 1, 2}, 3) == 2);
    assert(inversions((long long[]){2, 2, 1}, 3) == 2);
    assert(inversions((long long[]){5, 4, 3, 2, 1}, 5) == 10);
    assert(inversions(NULL, 0) == 0);
    return 0;
}
